            background:
              'Paws & Paddle was een snelgroeiend Brits huisdier-lifestylemerk, opgericht door voormalig dierenverpleegkundige Emma Thornton in 2019, dat premium hondenlijnen, manden en outdoormateriaal aanbood met een jaaromzet van £4,2 miljoen. De Britse markt voor huisdierproducten was £8 miljard waard, 34% van de Britse huishoudens had honden, en Emma zag een gat: geen groot huisdiermerk bood watersportuitrusting voor honden aan, ondanks de booming «hondvriendelijk avontuur»-trend op social media (#dogpaddle had 430 miljoen weergaven op TikTok). Het team van Emma had sterke relaties met 340 Britse huisdierretailers en 50+ outdoorwinkels, maar had een productiepartner nodig die SUP-boards kon ontwikkelen die specifiek voor hondengebruik waren ontworpen met passende veiligheidsvoorzieningen en tests.',
