            goal: 'Een uitgebreid «Canine SUP Certification»-programma ontwikkelen met boards van Afarer op maat, binnen 18 maanden 80 instructeurs in heel Australië trainen en certificeren en AU$1,2 miljoen aan programmaomzet genereren door boardsales, certificeringskosten en merchandise te combineren.',
