            goal: 'Een SUP-reddingseenheid van 12 boards opzetten die first-contact-interventie kan leveren in shorebreak- en ondiepwaterzones binnen 90 seconden na oproep, met geïntegreerde trauma- en wervelkolomuitrusting.',
